import { createServerFn } from "@tanstack/react-start";
import { requireAuth, requireAdmin } from "@/lib/auth-middleware";
import { query } from "./db.server";
import { slugify } from "./news-data";

export type ArticleRow = {
  id: number;
  title: string;
  slug: string;
  category: string;
  city: string;
  state: string;
  country: string;
  author: string;
  views: number;
  status: "Published" | "Draft" | "Review";
  date: string;
  excerpt: string;
  content: string;
  featuredImage: string;
  ogImage: string;
  imageCaption?: string;
  imageCredit?: string;
  metaTitle: string;
  metaDescription: string;
  tags: string;
  featured: boolean;
  newsType: "Standard" | "Breaking" | "Featured" | "Exclusive" | "Opinion" | "Video";
  journalistId: string;
  journalistName: string;
  access_level?: "Free" | "Premium";
};

// Admin only: list articles with server-side pagination & filtering
export const getAdminArticles = createServerFn({ method: "GET" })
  .middleware([requireAdmin])
  .validator(
    (data: { q?: string; category?: string; status?: string; page?: number; limit?: number }) =>
      data,
  )
  .handler(
    async ({
      data,
    }): Promise<{
      rows: ArticleRow[];
      total: number;
      totalPages: number;
      trashCount: number;
      scheduledCount: number;
    }> => {
      const { q = "", category = "All", status = "All", page = 1, limit = 20 } = data;
      // Auto-publish any past scheduled posts before fetching
      await query(
        "UPDATE articles SET status = 'Published' WHERE status = 'Scheduled' AND date <= NOW()",
      ).catch(() => {});

      // Safety cap — never return more than 200 rows in one admin request
      const safeLimit = Math.min(Math.max(1, limit), 200);
      const offset = (Math.max(1, page) - 1) * safeLimit;

      let filterSql = " WHERE 1=1";
      const params: any[] = [];

      const cleanQ = (q || "").trim();
      if (cleanQ) {
        // Split by whitespace so typing multiple words matches any/all words
        const words = cleanQ.split(/\s+/).filter(Boolean);
        if (words.length > 1) {
          // Multi-word search: match each word or full phrase
          const wordConditions: string[] = [];
          for (const w of words) {
            const wTerm = `%${w}%`;
            wordConditions.push("(title LIKE ? OR slug LIKE ? OR excerpt LIKE ? OR tags LIKE ?)");
            params.push(wTerm, wTerm, wTerm, wTerm);
          }
          filterSql += ` AND (${wordConditions.join(" AND ")})`;
        } else {
          filterSql += " AND (title LIKE ? OR slug LIKE ? OR excerpt LIKE ? OR tags LIKE ?)";
          const term = `%${cleanQ}%`;
          params.push(term, term, term, term);
        }
      }
      if (category && category !== "All") {
        filterSql += " AND (LOWER(category) = LOWER(?) OR LOWER(category) LIKE LOWER(?) OR LOWER(category) LIKE LOWER(?) OR LOWER(category) LIKE LOWER(?) OR LOWER(category) LIKE LOWER(?))";
        params.push(category, `${category},%`, `%, ${category}`, `%, ${category},%`, `%,${category},%`);
      }
      if (status && status !== "All") {
        if (status === "Scheduled") {
          filterSql += " AND (status = 'Scheduled' OR (status = 'Published' AND date > NOW()))";
        } else if (status === "Published") {
          filterSql += " AND status = 'Published' AND date <= NOW()";
        } else {
          filterSql += " AND status = ?";
          params.push(status);
        }
      } else {
        filterSql += " AND (status IS NULL OR status != 'Trash')";
      }

      // Run count, data, trash, and scheduled queries in parallel for speed
      const [countRes, rows, trashRes, scheduledRes] = await Promise.all([
        query(`SELECT COUNT(*) AS total FROM articles${filterSql}`, params),
        query(
          `SELECT id, title, slug, category, city, state, country, author, views, status, date,
                  excerpt, content, featuredImage, ogImage, imageCaption, imageCredit, metaTitle, metaDescription, tags,
                  featured, newsType, journalistId, journalistName, access_level
           FROM articles${filterSql} ORDER BY date DESC, id DESC LIMIT ? OFFSET ?`,
          [...params, safeLimit, offset],
        ),
        query("SELECT COUNT(*) AS total FROM articles WHERE status = 'Trash'"),
        query(
          "SELECT COUNT(*) AS total FROM articles WHERE status = 'Scheduled' OR (status = 'Published' AND date > NOW())",
        ),
      ]);

      const total = Number(countRes[0]?.total ?? 0);
      const trashCount = Number(trashRes[0]?.total ?? 0);
      const scheduledCount = Number(scheduledRes[0]?.total ?? 0);
      return {
        rows: rows.map((r: any) => ({ ...r, featured: Boolean(r.featured) })),
        total,
        trashCount,
        scheduledCount,
        totalPages: Math.max(1, Math.ceil(total / safeLimit)),
      };
    },
  );

// Admin only: get single article by ID with all fields
export const getAdminArticleById = createServerFn({ method: "GET" })
  .middleware([requireAdmin])
  .validator((id: number) => id)
  .handler(async ({ data: id }): Promise<ArticleRow | null> => {
    if (!id || id <= 0) return null;
    const rows = await query(
      `SELECT id, title, slug, category, city, state, country, author, views, status, date,
              excerpt, content, featuredImage, ogImage, imageCaption, imageCredit, metaTitle, metaDescription, tags,
              featured, newsType, journalistId, journalistName, access_level
       FROM articles WHERE id = ? LIMIT 1`,
      [id],
    );
    if (!rows || rows.length === 0) return null;
    const r = rows[0];
    return { ...r, featured: Boolean(r.featured) };
  });

// Admin only: save/create article
export const saveAdminArticle = createServerFn({ method: "POST" })
  .middleware([requireAdmin])
  .validator((data: any) => data)
  .handler(async ({ data }): Promise<ArticleRow> => {
    const r = data;
    const finalSlug = r.slug || slugify(r.title);

    const checkExisting = await query("SELECT id FROM articles WHERE slug = ? AND id != ?", [
      finalSlug,
      r.id || 0,
    ]);
    let slug = finalSlug;
    if (checkExisting.length > 0) {
      slug = `${finalSlug}-${Date.now().toString().slice(-4)}`;
    }

    const fields = [
      "title",
      "slug",
      "category",
      "city",
      "state",
      "country",
      "author",
      "views",
      "status",
      "date",
      "excerpt",
      "content",
      "featuredImage",
      "ogImage",
      "imageCaption",
      "imageCredit",
      "metaTitle",
      "metaDescription",
      "tags",
      "featured",
      "newsType",
      "journalistId",
      "journalistName",
      "access_level",
    ];

    let isExisting = false;
    let existingRow: any = null;
    if (r.id && Number(r.id) > 0) {
      const existingCheck = await query("SELECT * FROM articles WHERE id = ?", [r.id]);
      if (existingCheck.length > 0) {
        isExisting = true;
        existingRow = existingCheck[0];
      }
    }

    // Format date carefully: preserve original date if existing and not modified
    let formattedDate = new Date().toISOString().slice(0, 19).replace("T", " ");
    if (r.date) {
      let rawDate = String(r.date).replace("T", " ").replace("Z", "").trim();
      if (rawDate.length === 10) {
        const now = new Date();
        const pad = (n: number) => String(n).padStart(2, "0");
        rawDate += ` ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
      } else if (rawDate.length === 16) {
        rawDate += ":00";
      }
      formattedDate = rawDate.substring(0, 19);
    } else if (existingRow?.date) {
      formattedDate = String(existingRow.date).replace("T", " ").replace("Z", "").substring(0, 19);
    }

    let finalStatus = r.status || (existingRow?.status ?? "Draft");
    if (finalStatus === "Published" && new Date(formattedDate).getTime() > Date.now()) {
      finalStatus = "Scheduled";
    }

    const values = [
      r.title || (existingRow?.title ?? ""),
      slug,
      r.category || (existingRow?.category ?? "Uncategorized"),
      r.city ?? (existingRow?.city ?? ""),
      r.state ?? (existingRow?.state ?? ""),
      r.country ?? (existingRow?.country ?? ""),
      r.author || (existingRow?.author ?? "Admin User"),
      Number(r.views ?? existingRow?.views ?? 0) || 0,
      finalStatus,
      formattedDate,
      r.excerpt ?? (existingRow?.excerpt ?? ""),
      r.content ?? (existingRow?.content ?? ""),
      r.featuredImage ?? (existingRow?.featuredImage ?? ""),
      r.ogImage || r.featuredImage || (existingRow?.ogImage ?? ""),
      r.imageCaption ?? (existingRow?.imageCaption ?? ""),
      r.imageCredit ?? (existingRow?.imageCredit ?? ""),
      r.metaTitle ?? (existingRow?.metaTitle ?? ""),
      r.metaDescription ?? (existingRow?.metaDescription ?? ""),
      r.tags ?? (existingRow?.tags ?? ""),
      (r.featured !== undefined ? Boolean(r.featured) : Boolean(existingRow?.featured)) ? 1 : 0,
      r.newsType || (existingRow?.newsType ?? "Standard"),
      r.journalistId ?? (existingRow?.journalistId ?? ""),
      r.journalistName ?? (existingRow?.journalistName ?? ""),
      r.access_level || (existingRow?.access_level ?? "Free"),
    ];

    if (isExisting) {
      // Update
      const setClause = fields.map((f) => `${f} = ?`).join(", ");
      await query(`UPDATE articles SET ${setClause} WHERE id = ?`, [...values, r.id]);
      Object.keys(HOMEPAGE_CACHE).forEach((k) => delete HOMEPAGE_CACHE[k as any]);
      return { ...r, slug, id: r.id };
    } else {
      // Insert
      const colNames = fields.join(", ");
      const placeHolders = fields.map(() => "?").join(", ");
      const result = await query(
        `INSERT INTO articles (${colNames}) VALUES (${placeHolders})`,
        values,
      );
      Object.keys(HOMEPAGE_CACHE).forEach((k) => delete HOMEPAGE_CACHE[k as any]);
      return { ...r, slug, id: result.insertId };
    }
  });

// Admin only: get list of admin & editor author profiles for author dropdown
export const getAdminAuthorProfiles = createServerFn({ method: "GET" })
  .middleware([requireAdmin])
  .handler(async () => {
    try {
      const rows = await query(`
        SELECT DISTINCT u.id, COALESCE(p.display_name, u.display_name, u.email) AS name, u.username, u.email, p.phone, r.role
        FROM users u
        LEFT JOIN profiles p ON u.id = p.id
        JOIN user_roles r ON u.id = r.user_id
        WHERE r.role IN ('admin', 'editor', 'author', 'journalist')
        ORDER BY FIELD(r.role, 'admin', 'editor', 'author', 'journalist'), name ASC
      `);
      return rows.map((r: any) => ({
        id: r.id,
        name: r.name,
        username: r.username,
        role: r.role,
      }));
    } catch {
      const rows = await query(`
        SELECT DISTINCT 
          u.id, 
          COALESCE(p.display_name, u.display_name, u.email) AS name, 
          r.role
        FROM users u
        LEFT JOIN profiles p ON u.id = p.id
        JOIN user_roles r ON u.id = r.user_id
        WHERE r.role IN ('admin', 'editor', 'author', 'journalist')
        ORDER BY FIELD(r.role, 'admin', 'editor', 'author', 'journalist'), name ASC
      `);
      return rows.map((r: any) => ({
        id: r.id,
        name: r.name,
        role: r.role,
      }));
    }
  });

