// Admin only: import articles
export const importAdminArticles = createServerFn({ method: "POST" })
  .middleware([requireAdmin])
  .validator((articles: any[]) => articles)
  .handler(async ({ data: articles }) => {
    if (!articles || articles.length === 0) return { success: true };

    const fields = [
      "title",
      "slug",
      "category",
      "city",
      "state",
      "country",
      "author",
      "views",
      "status",
      "date",
      "excerpt",
      "content",
      "featuredImage",
      "ogImage",
      "metaTitle",
      "metaDescription",
      "tags",
      "featured",
      "newsType",
      "journalistId",
      "journalistName",
      "access_level",
    ];

    for (const r of articles) {
      const finalSlug = r.slug || slugify(r.title);

      let formattedDate = new Date().toISOString().slice(0, 19).replace("T", " ");
      if (r.date) {
        // Handle various date formats (e.g., '2026-07-22T02:33:09.000Z' -> '2026-07-22 02:33:09')
        formattedDate = String(r.date).replace("T", " ").replace("Z", "").substring(0, 19);
      }

      const values = [
        r.title || "Untitled",
        finalSlug,
        r.category || "Uncategorized",
        r.city || "",
        r.state || "",
        r.country || "",
        r.author || "Admin",
        Number(r.views) || 0,
        r.status || "Draft",
        formattedDate,
        r.excerpt || "",
        r.content || "",
        r.featuredImage || "",
        r.ogImage || r.featuredImage || "",
        r.metaTitle || "",
        r.metaDescription || "",
        r.tags || "",
        r.featured === "true" || r.featured === true || r.featured === 1 ? 1 : 0,
        r.newsType || "Standard",
        r.journalistId || "",
        r.journalistName || "",
        r.access_level || "Free",
      ];

      // Check if article with this ID or slug exists (Option A: Overwrite)
      const existing = await query("SELECT id FROM articles WHERE id = ? OR slug = ?", [
        r.id || 0,
        finalSlug,
      ]);

      if (existing.length > 0) {
        const idToUpdate = existing[0].id;
        const setClause = fields.map((f) => `${f} = ?`).join(", ");
        await query(`UPDATE articles SET ${setClause} WHERE id = ?`, [...values, idToUpdate]);
      } else {
        const colNames = fields.join(", ");
        const placeHolders = fields.map(() => "?").join(", ");
        await query(`INSERT INTO articles (${colNames}) VALUES (${placeHolders})`, values);
      }
    }
    Object.keys(HOMEPAGE_CACHE).forEach((k) => delete HOMEPAGE_CACHE[k as any]);
    return { success: true };
  });

// Reusable lightweight column projection for lists, cards, search, and feeds (omits heavy HTML content)
export const PUBLIC_CARD_COLUMNS = `
  id, title, slug, category, city, state, country, author, views, status, date,
  excerpt, featuredImage, ogImage, imageCaption, imageCredit, tags, featured, newsType, journalistId, journalistName, access_level
`;

// Public: get articles for search page
export const searchPublicArticles = createServerFn({ method: "GET" })
  .validator((data: { q?: string; category?: string; page?: number; limit?: number }) => data)
  .handler(async ({ data }) => {
    const { q = "", category = "All", page = 1, limit = 15 } = data;
    const offset = (page - 1) * limit;

    let countSql =
      "SELECT COUNT(*) as total FROM articles WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW()";
    let selectSql = `SELECT ${PUBLIC_CARD_COLUMNS} FROM articles WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW()`;
    const params: any[] = [];

    let filterSql = "";
    if (q) {
      filterSql += " AND (title LIKE ? OR excerpt LIKE ? OR content LIKE ?)";
      const term = `%${q}%`;
      params.push(term, term, term);
    }

    if (category && category !== "All") {
      filterSql += " AND (category = ? OR category LIKE ? OR category LIKE ? OR category LIKE ? OR category LIKE ?)";
      params.push(category, `${category},%`, `%, ${category}`, `%, ${category},%`, `%,${category},%`);
    }

    countSql += filterSql;
    selectSql += filterSql + " ORDER BY date DESC, id DESC LIMIT ? OFFSET ?";

    // pagination params must be numeric
    const countRes = await query(countSql, params);
    const total = countRes[0]?.total || 0;

    const selectParams = [...params, limit, offset];
    const items = await query(selectSql, selectParams);

    return {
      items: items.map((r: any) => ({
        ...r,
        featured: Boolean(r.featured),
      })),
      total,
      totalPages: Math.ceil(total / limit),
    };
  });

// Public: get single article by slug
export const getPublicArticleBySlug = createServerFn({ method: "GET" })
  .validator((slug: string) => slug)
  .handler(async ({ data: slug }) => {
    let decoded = slug;
    try {
      decoded = decodeURIComponent(slug);
    } catch (_) {}
    const rows = await query("SELECT * FROM articles WHERE slug = ? OR slug = ? LIMIT 1", [
      slug,
      decoded,
    ]);
    if (rows.length === 0) return null;

    const row = rows[0];
    if (row.status === "Trash") return null;
    if (
      (row.status === "Scheduled" || row.status === "Published") &&
      row.date &&
      new Date(row.date).getTime() > Date.now()
    ) {
      return null;
    }

    // Increment view count in background
    query("UPDATE articles SET views = views + 1 WHERE id = ?", [row.id]).catch((err) => {
      console.error("[MySQL] Failed to increment views:", err);
    });

    return {
      ...row,
      featured: Boolean(row.featured),
    };
  });

// Public: get related articles from database (matches category, excludes current article)
export const getPublicRelatedArticles = createServerFn({ method: "GET" })
  .validator((data: { category?: string; currentSlug?: string; limit?: number }) => data)
  .handler(async ({ data }) => {
    const { category, currentSlug = "", limit = 4 } = data;
    const safeLimit = Math.min(Math.max(1, limit), 8);
    let rows: any[] = [];

    // 1. First attempt: published articles in the same category
    if (category && category !== "All" && category.trim()) {
      rows = await query(
        `SELECT ${PUBLIC_CARD_COLUMNS} FROM articles 
         WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW() AND slug != ?
         AND (category = ? OR category LIKE ? OR category LIKE ? OR category LIKE ? OR category LIKE ?)
         ORDER BY date DESC, id DESC LIMIT ?`,
        [
          currentSlug,
          category,
          `${category},%`,
          `%, ${category}`,
          `%, ${category},%`,
          `%,${category},%`,
          safeLimit,
        ],
      );
    }

    // 2. If fewer than safeLimit, fill with other recent published articles
    if (rows.length < safeLimit) {
      const needed = safeLimit - rows.length;
      const excludeSlugs = [currentSlug, ...rows.map((r: any) => r.slug)].filter(Boolean);
      const placeholders = excludeSlugs.map(() => "?").join(", ");
      const fillSql =
        excludeSlugs.length > 0
          ? `SELECT ${PUBLIC_CARD_COLUMNS} FROM articles 
           WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW() AND slug NOT IN (${placeholders})
           ORDER BY date DESC, id DESC LIMIT ?`
          : `SELECT ${PUBLIC_CARD_COLUMNS} FROM articles 
           WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW()
           ORDER BY date DESC, id DESC LIMIT ?`;
      const fillParams = excludeSlugs.length > 0 ? [...excludeSlugs, needed] : [needed];
      const fillRows = await query(fillSql, fillParams);
      rows = [...rows, ...(fillRows || [])];
    }

    return (rows || []).map((r: any) => ({
      ...r,
      featured: Boolean(r.featured),
    }));
  });

// Public: get archive/latest articles
export const getPublicArchiveArticles = createServerFn({ method: "GET" })
  .validator(
    (data: { year?: string; month?: string; day?: string; page?: number; limit?: number }) => data,
  )
  .handler(async ({ data }) => {
    const { year, month, day, page = 1, limit = 15 } = data;
    const offset = (page - 1) * limit;

    let sql = `SELECT ${PUBLIC_CARD_COLUMNS} FROM articles WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW()`;
    let countSql =
      "SELECT COUNT(*) as total FROM articles WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW()";
    const params: any[] = [];

    if (year) {
      sql += " AND YEAR(date) = ?";
      countSql += " AND YEAR(date) = ?";
      params.push(Number(year));
    }
    if (month) {
      sql += " AND MONTH(date) = ?";
      countSql += " AND MONTH(date) = ?";
      params.push(Number(month));
    }
    if (day) {
      sql += " AND DAY(date) = ?";
      countSql += " AND DAY(date) = ?";
      params.push(Number(day));
    }

    sql += " ORDER BY date DESC, id DESC LIMIT ? OFFSET ?";

    const countRes = await query(countSql, params);
    const total = countRes[0]?.total || 0;

    const items = await query(sql, [...params, limit, offset]);

    return {
      items: items.map((r: any) => ({
        ...r,
        featured: Boolean(r.featured),
      })),
      total,
      totalPages: Math.ceil(total / limit),
    };
  });

const HOMEPAGE_CACHE: Record<number, { data: any; lastFetched: number; TTL: number }> = {};

// Public: get latest homepage articles (optimized lightweight payload)
export const getHomepageArticles = createServerFn({ method: "GET" })
  .validator((limit: any) => limit)
  .handler(async ({ data }) => {
    try {
      let rawLimit = 30;
      if (typeof data === "number") {
        rawLimit = data;
      } else if (typeof data === "string") {
        rawLimit = parseInt(data, 10) || 30;
      } else if (typeof data === "object" && data !== null) {
        rawLimit = parseInt(data.data || data.limit, 10) || 30;
      }
      const limitNum = Math.min(Math.max(1, rawLimit), 100);

      const now = Date.now();
      const cache = HOMEPAGE_CACHE[limitNum];

      if (cache && now - cache.lastFetched < cache.TTL) {
        console.log(`[Cache Hit] Serving homepage articles (limit: ${limitNum})`);
        return cache.data;
      }

      console.log(`[Cache Miss] Fetching homepage articles from MySQL (limit: ${limitNum})`);
      const items = await query(
        `SELECT id, title, slug, category, city, state, country, author, views, status, date,
                excerpt, SUBSTRING(content, 1, 2500) AS content, featuredImage, ogImage, tags, featured, newsType, journalistId, journalistName, access_level
         FROM articles 
         WHERE (status = 'Published' OR status = 'Scheduled') AND date <= NOW() 
         ORDER BY date DESC, id DESC 
         LIMIT ?`,
        [limitNum],
      );
      if (!Array.isArray(items)) {
        return [];
      }
      const mapped = items.map((r: any) => ({
        ...r,
        featured: Boolean(r.featured),
      }));

      HOMEPAGE_CACHE[limitNum] = {
        data: mapped,
        lastFetched: now,
        TTL: 5 * 1000, // 5 seconds
      };

      return mapped;
    } catch (err: any) {
      console.error("[getHomepageArticles] Error fetching articles:", err?.message || err);
      // Return cached data if available even if stale
      const fallbackLimit = 30;
      if (HOMEPAGE_CACHE[fallbackLimit]?.data) {
        return HOMEPAGE_CACHE[fallbackLimit].data;
      }
      return [];
    }
  });

// Admin: get dashboard statistics
export const getAdminDashboardStats = createServerFn({ method: "GET" })
  .middleware([requireAdmin])
  .handler(async () => {
    const [
      articlesCountRes,
      viewsCountRes,
      usersCountRes,
      commentsCountRes,
      subscribersCountRes,
      journalistsCountRes,
      recentArticles,
      topArticles,
      categoryStats,
    ] = await Promise.all([
      query("SELECT COUNT(*) as count FROM articles").catch(() => [{ count: 0 }]),
      query("SELECT COALESCE(SUM(views), 0) as count FROM articles").catch(() => [{ count: 0 }]),
      query("SELECT COUNT(*) as count FROM users").catch(() => [{ count: 0 }]),
      query("SELECT COUNT(*) as count FROM comments").catch(() => [{ count: 0 }]),
      query(`
        SELECT COUNT(DISTINCT user_id) as count 
        FROM user_roles 
        WHERE role IN ('premium', 'subscriber')
      `).catch(() => [{ count: 0 }]),
      query(`
        SELECT COUNT(DISTINCT user_id) as count 
        FROM user_roles 
        WHERE role = 'journalist'
      `).catch(async () => {
        return query("SELECT COUNT(*) as count FROM profiles WHERE journalist_id IS NOT NULL AND journalist_id != ''").catch(() => [{ count: 0 }]);
      }),
      query(`
        SELECT id, title, slug, category, views, date, featuredImage, featured, newsType, status 
        FROM articles 
        ORDER BY date DESC, id DESC 
        LIMIT 10
      `).catch(() => []),
      query(`
        SELECT id, title, slug, category, views, date, featuredImage, featured, newsType, status 
        FROM articles 
        ORDER BY views DESC, id DESC 
        LIMIT 30
      `).catch(() => []),
      query(`
        SELECT category as name, COUNT(*) as count, COALESCE(SUM(views), 0) as views 
        FROM articles 
        WHERE category IS NOT NULL AND category != '' 
        GROUP BY category 
        ORDER BY count DESC 
        LIMIT 8
      `).catch(() => []),
    ]);

    const totalArticles = Number(articlesCountRes?.[0]?.count) || 0;
    const totalViews = Number(viewsCountRes?.[0]?.count) || 0;
    const totalUsers = Number(usersCountRes?.[0]?.count) || 0;
    const totalComments = Number(commentsCountRes?.[0]?.count) || 0;
    let totalSubscribers = Number(subscribersCountRes?.[0]?.count) || 0;
    let totalJournalists = Number(journalistsCountRes?.[0]?.count) || 0;

    // If journalists or subscribers count from role table is 0, check profiles table
    if (totalJournalists === 0) {
      try {
        const pJournalists = await query("SELECT COUNT(*) as count FROM profiles WHERE journalist_id IS NOT NULL AND journalist_id != ''");
        totalJournalists = Number(pJournalists?.[0]?.count) || 0;
      } catch {}
    }

    // Subscription revenue: monthlyRate per subscriber
    const monthlyRate = 149;
    const totalRevenue = totalSubscribers > 0 ? totalSubscribers * monthlyRate : 0;

    const featuredArticles = (topArticles || []).filter(
      (a: any) => Boolean(a.featured) || a.newsType === "Featured" || a.newsType === "Exclusive"
    );

    return {
      totalArticles,
      totalViews,
      totalUsers,
      totalComments,
      totalSubscribers,
      totalJournalists,
      totalRevenue,
      recentArticles: recentArticles || [],
      topArticles: topArticles || [],
      featuredArticles: featuredArticles.length > 0 ? featuredArticles : (recentArticles || []).slice(0, 5),
      categoryStats: categoryStats || [],
      currencySymbol: "₹",
    };
  });

